import {Ajv, type ErrorObject, type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId?: string;
  sessionId?: string;
  workspaceId?: string;
  authHeaders?: Record<string, string>;
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinitionSource;
  executor: ToolExecutor;
}

export function normalizeToolResponse(raw: string | ToolResponse): ToolResponse {
  if (typeof raw === 'string') return {result: raw};
  return raw;
}

function formatValidationError(error: ErrorObject): string {
  const path = error.instancePath || '/';
  return `${path} ${error.message ?? 'is invalid'}`.trim();
}

export class ToolRegistry {
  private tools: RegisteredTool[] = [];
  private ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
  private validators = new WeakMap<object, ValidateFunction>();

  register(definition: ToolDefinitionSource, executor: ToolExecutor): void {
    this.tools.push({definition, executor});
  }

  getDefinitions(): ToolDefinition[] {
    return this.tools.map(({definition}) => (typeof definition === 'function' ? definition() : definition));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter((def): def is ToolDefinition & {promptInstructions: string} => !!def.promptInstructions)
      .map(def => `Tool "${def.name}": ${def.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(def => def.examplePrompts ?? []);
  }

  private getValidator(schema: Record<string, unknown>): ValidateFunction {
    let validator = this.validators.get(schema);
    if (!validator) {
      validator = this.ajv.compile(schema);
      this.validators.set(schema, validator);
    }
    return validator;
  }

  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const entry = this.tools.find(({definition}) => {
      const def = typeof definition === 'function' ? definition() : definition;
      return def.name === name;
    });

    if (!entry) {
      throw new Error(`Unknown tool: ${name}`);
    }

    const def = typeof entry.definition === 'function' ? entry.definition() : entry.definition;
    const validate = this.getValidator(def.inputSchema);
    if (!validate(input)) {
      const reasons = (validate.errors ?? []).map(formatValidationError);
      log.warn('tool', 'input validation failed', {name, reasons});
      return {result: `Invalid input for tool "${name}": ${reasons.join('; ')}`};
    }

    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const raw = await entry.executor(input, context);
    const response = normalizeToolResponse(raw);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof raw,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

